} from "~/types";
import { toTldrawColor } from "~/utils/tldrawColors";

export const DG_SCHEMA_EXPORT_VERSION = 1;

const discourseNodeSchema: z.ZodType<DiscourseNode> = z
  .object({
    id: z.string(),
    name: z.string(),
    format: z.string(),
    template: z.string().optional(),
    description: z.string().optional(),
    shortcut: z.string().optional(),
    color: z.string().optional(),
    tag: z.string().optional(),
    keyImage: z.boolean().optional(),
    folderPath: z.string().optional(),
    created: z.number(),
    modified: z.number(),
    importedFromRid: z.string().optional(),
    authorId: z.number().optional(),
  })
  .passthrough();

const relationImportStatusSchema = z.enum(["provisional", "accepted"]);

const discourseRelationTypeSchema: z.ZodType<
  DiscourseRelationType,
  z.ZodTypeDef,
  unknown
> = z
  .object({
    id: z.string(),
    label: z.string(),
    complement: z.string(),
    // Coerced, not rejected: vaults predating tldraw color names hold hex, and export copies settings verbatim, so a strict enum here fails a file the apply path could read.
    color: z
      .unknown()
      .transform((value) =>
        toTldrawColor(typeof value === "string" ? value : undefined),
      ),
    created: z.number(),
    modified: z.number(),
    importedFromRid: z.string().optional(),
    status: relationImportStatusSchema.optional(),
    authorId: z.number().optional(),
  })
  .passthrough();

const discourseRelationSchema: z.ZodType<DiscourseRelation> = z
  .object({
    id: z.string(),
    sourceId: z.string(),
    destinationId: z.string(),
    relationshipTypeId: z.string(),
    created: z.number(),
    modified: z.number(),
    importedFromRid: z.string().optional(),
    status: relationImportStatusSchema.optional(),
    authorId: z.number().optional(),
  })
  .passthrough();

const templateExportSchema: z.ZodType<DiscourseSchemaTemplate> = z
  .object({ name: z.string(), content: z.string() })
  .passthrough();

export const dgSchemaFileSchema: z.ZodType<
  DiscourseSchemaFile,
  z.ZodTypeDef,
  unknown
> = z
  .object({
    version: z.literal(DG_SCHEMA_EXPORT_VERSION),
    exportedAt: z.string(),
    pluginVersion: z.string(),
    vaultName: z.string(),
    vaultId: z.string(),
    nodeTypes: z.array(discourseNodeSchema),
    relationTypes: z.array(discourseRelationTypeSchema),
    discourseRelations: z.array(discourseRelationSchema),
    templates: z.array(templateExportSchema),
  })
