import { readFileSync, writeFileSync, mkdirSync, copyFileSync, readdirSync, rmSync } from "fs";
import path from "path";

const S = "/private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/0f317e52-46cd-4e60-bde3-483f6eb34e20/scratchpad";
const DEMO = `${S}/demo/dg-schema-lab-notebook.json`;
const SHOTS = `${S}/shots`;
const EXPORT_OUT = `${S}/demo/exported`;
const BACKUP = `${S}/backup`;
const demo = JSON.parse(readFileSync(DEMO, "utf8"));
mkdirSync(SHOTS, { recursive: true });
mkdirSync(EXPORT_OUT, { recursive: true });

const MODAL = ".modal-container .modal";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Crop to an element's rect (CSS px) with padding, so doc images show only the UI in question.
const shot = async ({ client, json }, name, selector = MODAL, pad = 12) => {
  await sleep(350);
  const r = await client.evaluate(`const el = document.querySelector(${json(selector)});
    if (!el) return null; const b = el.getBoundingClientRect();
    return { x: b.x, y: b.y, width: b.width, height: b.height };`);
  if (!r) throw new Error(`no element for shot ${name}: ${selector}`);
  const clip = { x: Math.max(0, r.x - pad), y: Math.max(0, r.y - pad), width: r.width + pad * 2, height: r.height + pad * 2, scale: 1 };
  const { data } = await client.send("Page.captureScreenshot", { format: "png", clip });
  writeFileSync(path.join(SHOTS, `${name}.png`), Buffer.from(data, "base64"));
};

const clickButton = ({ client, json }, text, { startsWith = false } = {}) =>
  client.evaluate(`const b = Array.from(document.querySelectorAll(${json(`${MODAL} button`)}))
    .find((el) => ${startsWith ? `el.textContent.trim().startsWith(${json(text)})` : `el.textContent.trim() === ${json(text)}`});
    if (!b) return false; b.click(); return true;`);

const waitText = ({ client, json }, text, selector = MODAL) =>
  client.waitFor(`return !!document.querySelector(${json(selector)})?.textContent.includes(${json(text)});`, { label: text, timeout: 10000 });

const scrollPanel = ({ client, json }, sectionHeading) =>
  client.evaluate(`const panel = document.querySelector(${json(`${MODAL} .max-h-96`)});
    const h = Array.from(panel.querySelectorAll("h4,h5")).find((el) => el.textContent.trim().startsWith(${json(sectionHeading)}));
    if (!h) return false; panel.scrollTop = h.closest("section").offsetTop - panel.offsetTop; return true;`);

// Electron dialogs can't be driven over CDP; stub them to fixed paths for this run only.
const stubDialogs = ({ client, json }, savePath) =>
  client.evaluate(`if (!window.__dgOrigRequire) window.__dgOrigRequire = window.require;
    const orig = window.__dgOrigRequire;
    const dialog = {
      showSaveDialog: async () => ({ canceled: false, filePath: ${json(savePath)} }),
      showOpenDialog: async () => ({ canceled: false, filePaths: [${json(DEMO)}] }),
    };
    window.require = (n) => (n === "electron" ? { dialog } : orig(n));
    return true;`);
const unstubDialogs = ({ client }) =>
